<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import type {Session} from '../FleetAndDocuments/contracts';
import {getSession,refreshCsrf} from '../FleetAndDocuments/api';
import {ApiError,request,failure,paginated} from '../Administration/api';
import {registrationDate} from '../FleetAndDocuments/presentation';
import {labels as stateLabels} from '../TransportAndDispatch/presentation';
import {instant,localInstant} from '../Workshop/presentation';
import {upload} from '../Expenses/api';
import type {DriverTrip,DriverExpense,DriverReport,DriverReading} from '../DriverPortal/contracts';
const props=defineProps<{session:Session|null}>();const emit=defineEmits<{denied:[error:unknown];session:[actor:Session];lock:[locked:boolean]}>();
interface Intent {actor:string;roles:string[];title:string;path:string;body:Record<string,unknown>;file:File|null}
const trips=ref<DriverTrip[]>([]),selected=ref<DriverTrip|null>(null),expenses=ref<DriverExpense[]>([]),records=ref<{reports:DriverReport[];odometer:DriverReading[]}>({reports:[],odometer:[]});
const historyExpenses=ref<DriverExpense[]>([]),historyPage=ref(1),historyLast=ref(1);
const loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),fields=ref<Record<string,string[]>>({}),page=ref(1),last=ref(1),pending=ref<Intent|null>(null);const recovery=new Map<string,Intent>();let generation=0;
const locked=computed(()=>busy.value||!!pending.value),driver=computed(()=>props.session?.roles.some(r=>['driver','administrator'].includes(r))??false);
const date=ref(localInstant()),observation=ref(''),reportType=ref('information'),reading=ref(''),readingType=ref('initial'),reason=ref(''),concept=ref(''),category=ref(''),amount=ref(''),currency=ref('CRC'),description=ref(''),receipt=ref<File|null>(null),receiptExpense=ref('');
watch(locked,value=>emit('lock',value),{immediate:true});
function report(e:unknown):void{const p=failure(e);error.value=p.message;fields.value=p.fields;if([401,403].includes(p.status)){trips.value=[];selected.value=null;expenses.value=[];records.value={reports:[],odometer:[]};emit('denied',p);}}
async function load(target=page.value):Promise<void>{if(loading.value||!props.session||!driver.value)return;const current=++generation;loading.value=true;error.value='';try{const result=await paginated<DriverTrip>(`/transport/my-trips?page=${target}`);if(current!==generation)return;trips.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;}catch(e){if(current===generation)report(e);}finally{if(current===generation)loading.value=false;}}
async function details(id:string):Promise<void>{if(loading.value||busy.value)return;const current=++generation;loading.value=true;error.value='';try{const [trip,costs]=await Promise.all([request<DriverTrip>(`/transport/my-trips/${id}`),paginated<DriverExpense>(`/expenses?trip_id=${id}&per_page=100`)]);if(current!==generation)return;selected.value=trip;expenses.value=costs.data;records.value={reports:trip.my_reports??[],odometer:trip.my_odometer??[]};}catch(e){if(current===generation)report(e);}finally{if(current===generation)loading.value=false;}}
async function ownHistory(target=1):Promise<void>{if(loading.value||busy.value||!props.session)return;const current=++generation;loading.value=true;try{const [history,costs]=await Promise.all([request<{reports:DriverReport[];odometer:DriverReading[];meta?:{current_page:number;last_page:number}}>(`/transport/my-records?page=${target}&per_page=25`),paginated<DriverExpense>(`/expenses?mine=1&page=${target}&per_page=25`)]);if(current!==generation)return;records.value=history;historyExpenses.value=costs.data;historyPage.value=target;historyLast.value=Math.max(history.meta?.last_page??1,costs.meta.last_page);}catch(e){if(current===generation)report(e);}finally{if(current===generation)loading.value=false;}}
watch(()=>props.session?`${props.session.id}:${props.session.roles.slice().sort().join('|')}`:'',()=>{const actor=props.session;generation++;trips.value=[];selected.value=null;expenses.value=[];records.value={reports:[],odometer:[]};historyExpenses.value=[];historyPage.value=1;historyLast.value=1;loading.value=false;pending.value=actor?recovery.get(actor.id)??null:null;if(actor)void load(1);},{immediate:true});
async function send(intent:Intent):Promise<void>{if(busy.value)return;busy.value=true;error.value='';fields.value={};success.value='';let attempted=false;const recovering=recovery.has(intent.actor);try{const actor=await getSession();emit('session',actor);if(actor.id!==intent.actor||actor.roles.slice().sort().join('|')!==intent.roles.slice().sort().join('|'))throw new ApiError(403,'La identidad o los permisos cambiaron. Recupera la operación con su cuenta original.');attempted=true;if(intent.file)await upload(intent.path,intent.body,intent.file);else await request(intent.path,'POST',intent.body);recovery.delete(intent.actor);pending.value=null;success.value=`${intent.title}: confirmado por el servidor.`;observation.value='';reading.value='';reason.value='';concept.value='';category.value='';amount.value='';description.value='';receipt.value=null;receiptExpense.value='';}catch(e){const p=failure(e);if(recovering||(attempted&&(p.status===0||p.status>=500||p.status===419))){recovery.set(intent.actor,intent);if(props.session?.id===intent.actor)pending.value=intent;}report(p);}finally{busy.value=false;}if(!pending.value&&props.session?.id===intent.actor){const tripId=selected.value?.id;await load();if(tripId)await details(tripId);}}
async function command(title:string,path:string,body:Record<string,unknown>,file:File|null=null):Promise<void>{if(locked.value||!props.session||!driver.value)return;if(!confirm(`${title}. ¿Confirmas los datos?`))return;await send({actor:props.session.id,roles:[...props.session.roles],title,path,body:{...body,request_key:crypto.randomUUID()},file});}
async function retry():Promise<void>{if(pending.value&&confirm('Reenviar exactamente la misma operación con su clave original.'))await send(pending.value);}
async function recover():Promise<void>{if(busy.value)return;try{await refreshCsrf();const actor=await getSession();emit('session',actor);pending.value=recovery.get(actor.id)??null;}catch(e){report(e);}}
function addReport():void{if(selected.value)void command('Registrar reporte',`/transport/my-trips/${selected.value.id}/reports`,{type:reportType.value,information:{observation:observation.value},occurred_at:instant(date.value)});}
function addReading():void{const assignment=selected.value?.assets.find(a=>a.type==='tractor_unit');if(selected.value&&assignment)void command('Registrar kilometraje',`/transport/my-trips/${selected.value.id}/odometer`,{tractor_assignment_id:assignment.id,reading_type:readingType.value,reading_value:reading.value,reason:reason.value,occurred_at:instant(date.value)});}
function addExpense():void{if(selected.value)void command('Registrar gasto pendiente','/expenses',{trip_id:selected.value.id,concept:concept.value,category:category.value,amount:amount.value,currency:currency.value,description:description.value||null,occurred_at:instant(date.value)});}
function fileChanged(event:Event):void{receipt.value=(event.target as HTMLInputElement).files?.[0]??null;}
function unload(e:BeforeUnloadEvent):void{if(locked.value){e.preventDefault();e.returnValue='';}}window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>{generation++;window.removeEventListener('beforeunload',unload);emit('lock',false);});
</script>
<template><section class="space-y-4"><h2 class="text-xl font-semibold">Mis viajes asignados</h2><p class="notice-info">Portal en línea. No permite captura sin conexión. Los reportes nunca inician, finalizan ni cierran oficialmente un viaje.</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><ul v-if="Object.keys(fields).length" role="alert" class="notice-error"><template v-for="(messages,key) in fields" :key="key"><li v-for="message in messages" :key="message">{{key}}: {{message}}</li></template></ul><p v-if="success" role="status" class="notice-success">{{success}}</p><button v-if="!session" class="btn-secondary" :disabled="busy" @click="recover">Comprobar sesión y recuperar operación</button><section v-if="pending&&session" class="panel space-y-3"><h3 class="font-semibold">Registro pendiente de confirmación</h3><p>{{pending.title}}. No se asume que falló. Conservamos su contenido y clave en memoria mientras esta página siga abierta.</p><button class="btn-primary" :disabled="busy" @click="retry">Reintentar la misma operación</button><button class="btn-secondary" :disabled="busy" @click="recover">Comprobar sesión</button></section><template v-if="session&&driver"><div class="flex flex-wrap gap-3"><button class="btn-secondary" :disabled="loading||busy" @click="load()">Actualizar viajes</button><button class="btn-secondary" :disabled="loading||busy" @click="ownHistory()">Consultar mis registros históricos</button></div><p v-if="loading" role="status">Consultando registros…</p><p v-else-if="!trips.length">No hay viajes asignados vigentes.</p><div class="grid gap-3 md:grid-cols-2"><article v-for="trip in trips" :key="trip.id" class="panel space-y-2"><h3 class="font-semibold">{{trip.route.name}} · {{trip.product}}</h3><p>{{trip.route.origin}} → {{trip.route.destination}}</p><p class="break-all text-sm">Viaje {{trip.id}}</p><p>{{stateLabels[trip.execution_status]??trip.execution_status}} · {{stateLabels[trip.administrative_status]??trip.administrative_status}}</p><p>Programación: {{trip.scheduled_start_at?registrationDate(trip.scheduled_start_at):'Sin fecha registrada'}}</p><p v-for="asset in trip.assets" :key="asset.code">{{asset.type==='tanker'?'Cisterna':'Cabezal'}}: {{asset.code}}</p><button class="btn-primary" :disabled="loading||locked" @click="details(trip.id)">Consultar viaje y registrar información</button></article></div><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||busy||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||busy||page>=last" @click="load(page+1)">Siguiente</button></div><section v-if="selected" class="panel space-y-5"><h3 class="text-xl font-semibold">Operación del viaje: {{selected.route.name}}</h3><p>La asignación vigente y los permisos se validan nuevamente al confirmar cada registro.</p><label class="block">Fecha y hora del registro (Costa Rica)<input v-model="date" class="field" type="datetime-local" step="1" :disabled="locked" required></label><div class="grid gap-5 lg:grid-cols-2"><form class="space-y-3" @submit.prevent="addReport"><h4 class="font-semibold">Eventos y observaciones</h4><label class="block">Tipo de reporte<select aria-label="Tipo de reporte" v-model="reportType" class="field" :disabled="locked"><option value="information">Información</option><option value="incident">Incidencia o avería</option><option value="completion_report">Reporte informativo de terminación</option></select></label><label class="block">Observación<textarea v-model="observation" class="field" maxlength="2000" required :disabled="locked"></textarea></label><button class="btn-primary" :disabled="locked||!date">Registrar reporte</button></form><form class="space-y-3" @submit.prevent="addReading"><h4 class="font-semibold">Lectura de odómetro</h4><label class="block">Tipo de lectura<select aria-label="Tipo de lectura" v-model="readingType" class="field" :disabled="locked"><option value="initial">Inicial</option><option value="final">Final</option></select></label><label class="block">Kilometraje<input v-model="reading" class="field" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required :disabled="locked"></label><label class="block">Motivo de lectura<input v-model="reason" class="field" maxlength="2000" required :disabled="locked"></label><button class="btn-primary" :disabled="locked||!date||!selected.assets.some(a=>a.type==='tractor_unit')">Registrar kilometraje</button></form></div><form class="space-y-3 border-t pt-4" @submit.prevent="addExpense"><h4 class="font-semibold">Gasto del viaje</h4><p class="text-sm">Se registra pendiente de decisión del administrador. El comprobante se adjunta al gasto confirmado, sin crear otro gasto.</p><div class="grid gap-3 sm:grid-cols-2"><label>Concepto<input v-model="concept" class="field" required maxlength="255" :disabled="locked"></label><label>Categoría<input v-model="category" class="field" required maxlength="255" :disabled="locked"></label><label>Monto<input v-model="amount" class="field" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required :disabled="locked"></label><label>Moneda<select aria-label="Moneda" v-model="currency" class="field" :disabled="locked"><option>CRC</option><option>USD</option></select></label></div><label class="block">Descripción<textarea v-model="description" class="field" :disabled="locked"></textarea></label><button class="btn-primary" :disabled="locked||!date">Registrar gasto pendiente</button></form><section class="space-y-3"><h4 class="font-semibold">Mis gastos de este viaje</h4><p v-if="!expenses.length">No hay gastos registrados.</p><article v-for="expense in expenses" :key="expense.id" class="rounded border border-blue-200 p-3"><p>{{expense.concept}} · {{expense.currency}} {{expense.amount}} · {{expense.status==='approved'?'Aprobado':expense.status==='rejected'?'Rechazado':'Pendiente'}}</p><a v-for="proof in expense.receipts" :key="proof.id" :href="`/api/expenses/receipts/${proof.id}/download`" class="text-blue-800 underline block">Descargar comprobante autorizado</a></article><form v-if="expenses.length" class="space-y-3" @submit.prevent="receipt&&receiptExpense&&command('Adjuntar comprobante',`/expenses/${receiptExpense}/receipts`,{},receipt)"><label class="block">Gasto para adjuntar comprobante<select aria-label="Gasto para adjuntar comprobante" v-model="receiptExpense" class="field" required :disabled="locked"><option value="">Seleccionar gasto</option><option v-for="expense in expenses" :key="expense.id" :value="expense.id">{{expense.concept}} · {{expense.currency}} {{expense.amount}}</option></select></label><label class="block">Comprobante PDF, JPG o PNG (máximo 10 MB)<input type="file" class="field" accept="application/pdf,image/jpeg,image/png" required :disabled="locked" @change="fileChanged"></label><button class="btn-primary" :disabled="locked||!receipt||!receiptExpense">Adjuntar comprobante privado</button></form></section></section><section class="panel space-y-3"><h3 class="font-semibold">Historial de mis registros</h3><article v-for="item in records.reports" :key="item.id" class="border-b pb-2"><p>{{item.type==='incident'?'Incidencia':item.type==='completion_report'?'Reporte informativo de terminación':'Información'}} · {{registrationDate(item.occurred_at)}}</p><p class="whitespace-pre-wrap break-words">{{item.information.observation}}</p></article><p v-for="item in records.odometer" :key="item.id">{{item.reading_type==='initial'?'Inicial':'Final'}}: {{item.reading_value}} km · {{registrationDate(item.occurred_at)}} · {{item.reason}}</p><p v-if="!records.reports.length&&!records.odometer.length">No hay registros propios para mostrar.</p><h4 class="font-semibold">Historial de mis gastos</h4><article v-for="expense in historyExpenses" :key="expense.id" class="border-b py-2"><p>{{expense.concept}} · {{expense.currency}} {{expense.amount}} · {{expense.status==='approved'?'Aprobado':expense.status==='rejected'?'Rechazado':'Pendiente'}}</p><a v-for="proof in expense.receipts" :key="proof.id" :href="`/api/expenses/receipts/${proof.id}/download`" class="text-blue-800 underline block">Descargar comprobante histórico autorizado</a></article><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||busy||historyPage<=1" @click="ownHistory(historyPage-1)">Registros anteriores</button><span>Página histórica {{historyPage}} de {{historyLast}}</span><button class="btn-secondary" :disabled="loading||busy||historyPage>=historyLast" @click="ownHistory(historyPage+1)">Más registros</button></div></section></template></section></template>
